contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 _value) public {
        require(_value <= c.totalSupply());
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.burn(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && c.totalSupply() == beforeSupply - _value || reverted && c.totalSupply() == beforeSupply);
    }
}

