pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 _value) internal {
        vm.assume(_value <= c.totalSupply());
        uint256 beforeSupply;
        try c.totalSupply() returns (uint256 __r) { beforeSupply = __r; } catch { return; }
        bool reverted;
        try c.burn(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && c.totalSupply() == beforeSupply - _value || reverted && c.totalSupply() == beforeSupply);
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
